// Tiny directly original numerical controls, independent of rendered raster outcomes.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.lang.reflect.*;
public class BeamFiltersControlProbe extends BeamsProbe {
 public BeamFiltersControlProbe(Book b,SortedSet<Integer> ids){super(b,ids);}
 static Object buffer(int w,int h,byte[] pixels)throws Exception{return construct("ij.process.ByteProcessor",new Class<?>[]{int.class,int.class,byte[].class,java.awt.image.ColorModel.class},w,h,pixels,null);}
 public void process(){try{Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet"),picture=call(sheet,"getPicture"),sb=construct("org.audiveris.omr.sheet.beam.SpotsBuilder",new Class<?>[]{cls("org.audiveris.omr.sheet.Sheet")},sheet);List<String> rows=new ArrayList<>();int[][] dims={{1,1},{2,3},{3,2},{3,3},{5,4},{7,9},{17,15},{31,23}};
 for(int[] dim:dims)for(int pattern=0;pattern<4;pattern++){int w=dim[0],h=dim[1];byte[] data=new byte[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int v=switch(pattern){case 0->(x==w/2&&y==h/2?0:255);case 1->((x+y)%2==0?0:255);case 2->(x*37+y*59+17)%256;default->0;};data[y*w+x]=(byte)v;}Object input=buffer(w,h,data);String start=mask(input),median="null",gaussian="null",filterError="null";try{median=mask(call(picture,"medianFiltered",call(input,"duplicate")));gaussian=mask(call(picture,"gaussianFiltered",call(input,"duplicate")));}catch(Exception ex){Throwable t=ex instanceof InvocationTargetException?((InvocationTargetException)ex).getCause():ex;filterError=q(t.toString());}
 List<String> closes=new ArrayList<>();for(double beam:new double[]{1,2,3,8,9,16,32}){Object cp=call(input,"duplicate");String error="null",close="null",threshold="null";try{call(sb,"close",cp,beam);close=mask(cp);call(cp,"threshold",140);threshold=mask(cp);}catch(Exception ex){Throwable t=ex instanceof InvocationTargetException?((InvocationTargetException)ex).getCause():ex;error=q(t.toString());}closes.add("{\"beam\":"+beam+",\"closed\":"+close+",\"threshold_140\":"+threshold+",\"original_exception\":"+error+"}");}
 rows.add("{\"width\":"+w+",\"height\":"+h+",\"pattern\":"+pattern+",\"input\":"+start+",\"median\":"+median+",\"gaussian\":"+gaussian+",\"filter_exception\":"+filterError+",\"closes\":["+String.join(",",closes)+"]}");}
 Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"controlled_input\":true,\"native_outputs_used\":false,\"masks_from_original_methods\":true,\"spots_constants\":"+constants("org.audiveris.omr.sheet.beam.SpotsBuilder")+",\"picture_constants\":"+constants("org.audiveris.omr.sheet.Picture")+",\"cases\":["+String.join(",",rows)+"]}\n");}catch(Exception ex){throw new RuntimeException(ex);}}
}
